function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value of nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 0 || k > 100000000000000) return 'k is an integer from 0 to 10^14.';
  return null;
}

