function maxFrequencyScore(nums, k) {
  nums.sort((a, b) => a - b);
  const n = nums.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + nums[i];
  }
  const cost = (left, right) => {
    const mid = (left + right) >> 1;
    const raiseLow = nums[mid] * (mid - left) - (prefix[mid] - prefix[left]);
    const lowerHigh = prefix[right + 1] - prefix[mid + 1] - nums[mid] * (right - mid);
    return raiseLow + lowerHigh;
  };
  let left = 0;
  let best = 0;
  for (let right = 0; right < n; right++) {
    while (cost(left, right) > k) {
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

