function maxFrequencyScore(nums, k) {
  // For every possible meeting value, greedily pull in the closest numbers first.
  let best = 0;
  for (const target of nums) {
    const distances = nums.map(v => Math.abs(v - target)).sort((a, b) => a - b);
    let spent = 0;
    let count = 0;
    for (const d of distances) {
      if (spent + d > k) break;
      spent += d;
      count++;
    }
    best = Math.max(best, count);
  }
  return best;
}

